import{_ as r}from"./plugin-vue_export-helper-c27b6911.js";import{r as t,o as l,c as o,a as n,b as e,e as i,w as c,f as d}from"./app-500d1f03.js";const v="/assets/image-20230227231928988-e08e5dd7.png",u={},p=n("h1",{id:"redis",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#redis","aria-hidden":"true"},"#"),e(" Redis")],-1),g=n("h2",{id:"redis持久化",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#redis持久化","aria-hidden":"true"},"#"),e(" Redis持久化")],-1),b={href:"https://redis.io/docs/manual/persistence/",target:"_blank",rel:"noopener noreferrer"},h=d(`<h3 id="rdb快照-snapshot" tabindex="-1"><a class="header-anchor" href="#rdb快照-snapshot" aria-hidden="true">#</a> RDB快照（snapshot）</h3><ul><li><p>存储：默认情况下， Redis 将<strong>内存数据库快照</strong>保存在名字为 <strong>dump.rdb</strong> 的二进制文件中。</p></li><li><p>自动生成快照：<br> 如：下面意思为满足“ 60 秒内有至少有 1000 个键被改动”这一条件时， 自动保存一次数据集</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># save 60 1000    //关闭RDB只需要将所有的save保存策略注释掉即可
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li><li><p>手动生成快照：<br> redis客户端执行命令 <strong>save</strong> 或 <strong>bgsave</strong> 可以生成 dump.rdb 文件。每次命令执行都会将所有redis内存快照到一个新的rdb文件里，并覆盖原有rdb快照文件。</p></li></ul><p><strong>bgsave的写时复制( COW) 机制</strong></p><p>Redis 借助操作系统提供的<strong>写时复制技术（Copy-On-Write, COW）</strong>，在生成快照的同时，依然可以正常处理写命令。简单来说，bgsave 子进程是由主进程 fork 生成的，可以共享主进程的所有内存数据（今天的系统中，系统调用 fork，不会立刻触发对父进程的物理内存的拷贝，此时父子进程最终都会指向这个内存，即共享父进程内存）。bgsave 子进程运行后，开始读取主进程的内存数据，并把它们写入 RDB 文件。此时，如果主线程对这些数据也都是读操作，那么，主线程和 bgsave 子进程相互不影响。但是，如果主线程要修改一块数据，那么，这块数据就会被复制一份，生成该数据的副本。然后，bgsave 子进程会把这个副本数据写入 RDB 文件，而在这个过程中，主线程仍然可以直接修改原来的数据。</p>`,4),m=d(`<p><strong>save与bgsave对比：</strong></p><table><thead><tr><th><strong>命令</strong></th><th><strong>save</strong></th><th><strong>bgsave</strong></th></tr></thead><tbody><tr><td>IO类型</td><td>同步</td><td>异步</td></tr><tr><td>是否阻塞redis其它命令</td><td>是</td><td>否(在生成子进程执行调用 fork 函数时会有短暂阻塞)</td></tr><tr><td>复杂度</td><td>O(n)</td><td>O(n)</td></tr><tr><td>优点</td><td>不会消耗额外内存</td><td>不阻塞客户端命令</td></tr><tr><td>缺点</td><td>阻塞客户端命令</td><td>需要 fork子进程，消耗内存</td></tr></tbody></table><p><strong>配置自动生成rdb文件后台使用的是bgsave方式。</strong></p><h3 id="aof-append-only-file" tabindex="-1"><a class="header-anchor" href="#aof-append-only-file" aria-hidden="true">#</a> <strong>AOF（append-only file）</strong></h3><h4 id="aof-简介" tabindex="-1"><a class="header-anchor" href="#aof-简介" aria-hidden="true">#</a> AOF 简介</h4><p>快照功能并不是非常耐久（durable）： 如果 Redis 因为某些原因而造成故障停机， 那么服务器将丢失最近写入、且仍未保存到快照中的那些数据。从 1.1 版本开始， Redis 增加了一种完全耐久的持久化方式： AOF 持久化，将<strong>修改的</strong>每一条指令记录进文件appendonly.aof中(先写入os cache，每隔一段时间fsync到磁盘)</p><p>比如执行命令**“set qiuchi 666”**，aof文件里会记录如下数据：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>*3
$3
set
$6
qiuchi
$3
666
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这是一种 resp 协议格式数据，星号后面的数字代表命令有多少个参数，$号后面的数字代表这个参数有几个字符。</p><p>注意，如果执行带过期时间的set命令，aof 文件里记录的是并不是执行的原始命令，而是记录key过期的<strong>时间戳</strong>。</p><p>比如执行**“set qiuchi 888 ex 1000”**（设置键过期时间为1000秒，1000秒后自动删除），对应 aof 文件里记录如下</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>*3
$3
set
$6
qiuchi
$3
888
*3
$9
PEXPIREAT
$6
qiuchi
$13
1604299786302            
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="aof-开启" tabindex="-1"><a class="header-anchor" href="#aof-开启" aria-hidden="true">#</a> AOF 开启</h4><p>通过修改配置文件打开 AOF 功能：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code> # appendonly yes              
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div>`,15),f={href:"http://redisdoc.com/string/set.html#set",target:"_blank",rel:"noopener noreferrer"},x=d(`<p>这样的话， 当 Redis 重新启动时， 程序就可以通过重新执行 AOF 文件中的命令来达到重建数据集的目的。</p><h4 id="fsync-时效" tabindex="-1"><a class="header-anchor" href="#fsync-时效" aria-hidden="true">#</a> fsync 时效</h4><p>你可以配置 Redis 多久才将数据 fsync 到磁盘一次（即往磁盘延迟写的时间间隔）。</p><p>有三个选项：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>appendfsync always：每次有新命令追加到 AOF 文件时就执行一次 fsync ，非常慢，也非常安全。 
appendfsync everysec：每秒 fsync 一次，足够快，并且在故障时只会丢失 1 秒钟的数据。
appendfsync no：从不 fsync ，将数据交给操作系统来处理。更快，也更不安全的选择。   
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>推荐（并且也是默认）的措施为每秒 fsync 一次， 这种 fsync 策略可以兼顾速度和安全性。</p><h4 id="aof-重写" tabindex="-1"><a class="header-anchor" href="#aof-重写" aria-hidden="true">#</a> <strong>AOF 重写</strong></h4><p>AOF文件里可能有太多没用指令，所以 AOF 会定期根据<strong>内存的最新数据</strong>生成 aof 文件。</p><p>例如，执行了如下几条命令：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>127.0.0.1:6379&gt; incr readcount
(integer) 1
127.0.0.1:6379&gt; incr readcount
(integer) 2
127.0.0.1:6379&gt; incr readcount
(integer) 3
127.0.0.1:6379&gt; incr readcount
(integer) 4
127.0.0.1:6379&gt; incr readcount
(integer) 5
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>​</p><p>重写后AOF文件里变成</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>*3
$3
SET
$2
readcount
$1
5
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>​</p><p><strong>控制AOF自动重写频率：</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># auto-aof-rewrite-min-size 64mb   //aof文件至少要达到64M才会自动重写，文件太小恢复速度本来就很快，重写的意义不大
# auto-aof-rewrite-percentage 100  //aof文件自上一次重写后文件大小增长了100%则再次触发重写  
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>AOF 手动重写：</strong></p><p>进入redis客户端执行命令:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>bgrewriteaof
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>注意，<strong>AOF重写redis会fork出一个子进程去做(与bgsave命令类似)，不会对redis正常命令处理有太多影响</strong></p><p><strong>AOF 重写机制：</strong></p><p>Redis &gt;= 7.0：</p><ul><li>Redis fork，得到一个子进程和一个父进程。</li><li>子进程在一个临时文件中写下新的基本的 AOF 文件。</li><li>在子进程写的时候，父进程将增量的更新写到一个新的增量 AOF 文件中。（此时如果重写失败，旧的 AOF 文件和增量文件（如果有的话），就构成了完整的记录）。</li><li>子进程将基本 AOF 文件写完后，给父进程发一个信息，子进程写的新的基本文件和父进程的增量文件就组成（原子操作）了新 AOF 文件。</li><li>删除旧的 AOF 文件和无用的增量文件即可。</li></ul><p>Redis &lt; 7.0：</p><ul><li>Redis fork，得到一个子进程和一个父进程。</li><li>子进程在一个临时文件中写下新的 AOF 文件。</li><li>在子进程写的时候，父进程将改变更新到缓存中，同时继续更新旧的 AOF 文件。（此时如果重写失败，AOF 文件里依旧是完整记录）。</li><li>子进程将基本 AOF 文件写完后，给父进程发一个信息，父进程会将缓存中内容追加到子进程产生的新 AOF 文件中。</li><li>原子性地将新文件重命名为旧的文件名。</li></ul><blockquote><p>新的方法避免了以前在重写时很占内存的缺点。</p></blockquote><h3 id="rdb-和-aof-我应该用哪一个" tabindex="-1"><a class="header-anchor" href="#rdb-和-aof-我应该用哪一个" aria-hidden="true">#</a> RDB 和 AOF ，我应该用哪一个？</h3><table><thead><tr><th><strong>命令</strong></th><th><strong>RDB</strong></th><th><strong>AOF</strong></th></tr></thead><tbody><tr><td>启动优先级</td><td>低</td><td>高</td></tr><tr><td>体积</td><td>小</td><td>大</td></tr><tr><td>恢复速度</td><td>快</td><td>慢</td></tr><tr><td>数据安全性</td><td>容易丢数据</td><td>根据策略决定</td></tr></tbody></table><p>生产环境可以都启用，redis启动时如果既有rdb文件又有aof文件则优先选择aof文件恢复数据，因为aof一般来说数据更全一点。</p><h3 id="redis-4-0-混合持久化" tabindex="-1"><a class="header-anchor" href="#redis-4-0-混合持久化" aria-hidden="true">#</a> <strong>Redis 4.0 混合持久化</strong></h3><p>重启 Redis 时，我们很少使用 RDB来恢复内存状态，因为会丢失大量数据。我们通常使用 AOF 日志重放，但是重放 AOF 日志性能相对 RDB来说要慢很多，这样在 Redis 实例很大的情况下，启动需要花费很长的时间。 Redis 4.0 为了解决这个问题，带来了一个新的持久化选项——混合持久化。</p><p>通过如下配置可以开启混合持久化(<strong>必须先开启aof</strong>)：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># aof-use-rdb-preamble yes   
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>如果开启了混合持久化，<strong>AOF在重写时</strong>，不再是单纯将内存数据转换为RESP命令写入AOF文件，而是将重写<strong>这一刻之前</strong>的内存做RDB快照处理，并且将RDB快照内容和<strong>增量的</strong>AOF修改内存数据的命令存在一起，都写入新的AOF文件，新的文件一开始不叫appendonly.aof，等到重写完新的AOF文件才会进行改名，覆盖原有的AOF文件，完成新旧两个AOF文件的替换。</p><p>于是在 Redis 重启的时候，可以先加载 RDB 的内容，然后再重放增量 AOF 日志就可以完全替代之前的 AOF 全量文件重放，因此重启效率大幅得到提升。</p><p>混合持久化AOF文件结构如下：</p><figure><img src="`+v+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>Redis数据备份策略</strong></p><ol><li>写 crontab 定时调度脚本，每小时都 copy 一份 rdb 或 aof 的备份到一个目录中去，仅仅保留最近 48 小时的备份</li><li>每天都保留一份当日的数据备份到一个目录中去，可以保留最近1个月的备份</li><li>每次 copy 备份的时候，都把太旧的备份给删了</li><li>每天晚上将当前机器上的备份复制一份到其他机器上，以防机器损坏</li></ol>',39);function O(A,F){const s=t("ExternalLinkIcon"),a=t("RouterLink");return l(),o("div",null,[p,g,n("p",null,[e("官网地址："),n("a",b,[e("https://redis.io/docs/manual/persistence/"),i(s)])]),h,n("blockquote",null,[n("p",null,[e("详见"),i(a,{to:"/data/Redis_COW.html"},{default:c(()=>[e("《Redis写时拷贝（COW）总结》")]),_:1}),e("。")])]),m,n("p",null,[e("从现在开始， 每当 Redis 执行一个改变数据集的命令时（比如 "),n("a",f,[e("SET"),i(s)]),e("）， 这个命令就会被追加到 AOF 文件的末尾。")]),x])}const y=r(u,[["render",O],["__file","11redis_persistence.html.vue"]]);export{y as default};
